# work/words.json -> web/al_words.js  (WF = [[word, startFrame, endFrame], ...], NF = total frames)
import json, sys, math
W = json.load(open('work/words.json')); nf = int(sys.argv[1]) if len(sys.argv) > 1 else int(math.ceil((W[-1]['e'] + 1.3) * 30))
import os, subprocess
if len(sys.argv) < 2 and os.path.exists('audio/voice.wav'): nf = int(math.ceil(float(subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', 'audio/voice.wav'], capture_output=True, text=True).stdout) * 30))
open('web/al_words.js', 'w').write('// [AL-story] generated by gen_words.py from work/words.json\nexport const WF = ' + json.dumps([[w['w'], int(round(w['s'] * 30)), int(round(w['e'] * 30))] for w in W]) + ';\nexport const NF = ' + str(nf) + ';\n')
print('words', len(W), 'NF', nf)
